CREATE TABLE IF NOT EXISTS campus_controls (user_id VARCHAR(32) PRIMARY KEY,muted INTEGER NOT NULL DEFAULT 0,read_only INTEGER NOT NULL DEFAULT 0,suspended INTEGER NOT NULL DEFAULT 0,version INTEGER NOT NULL DEFAULT 1,reason VARCHAR(250) NOT NULL,updated_at VARCHAR(30) NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS campus_enrollments (user_id VARCHAR(32) NOT NULL,course_id VARCHAR(20) NOT NULL,joined_at VARCHAR(30) NOT NULL,PRIMARY KEY(user_id,course_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS campus_rooms (course_id VARCHAR(20) PRIMARY KEY,locked INTEGER NOT NULL DEFAULT 0,version INTEGER NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS campus_messages (id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id VARCHAR(32) NOT NULL,course_id VARCHAR(20) NOT NULL,body TEXT NOT NULL,status VARCHAR(12) NOT NULL,created_at VARCHAR(30) NOT NULL,request_key VARCHAR(32) NOT NULL UNIQUE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS campus_reports (message_id BIGINT NOT NULL,user_id VARCHAR(32) NOT NULL,created_at VARCHAR(30) NOT NULL,PRIMARY KEY(message_id,user_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS campus_avatars (user_id VARCHAR(32) PRIMARY KEY,image_data MEDIUMBLOB NOT NULL,updated_at VARCHAR(30) NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS campus_audit (id BIGINT PRIMARY KEY AUTO_INCREMENT,actor_id VARCHAR(32) NOT NULL,action VARCHAR(40) NOT NULL,subject VARCHAR(50) NOT NULL,detail_json TEXT NOT NULL,created_at VARCHAR(30) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
